INSERT INTO _dex_wave_f_profiles_0083 (
  target_table, slug, canonical_profile, feature
) VALUES ('successful_exchanges', 'hyperliquid', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"dex:hyperliquid","type":"dex","slug":"hyperliquid","name":"Hyperliquid DEX","aliases":["Hyperliquid exchange","HyperCore exchange"]},"classification":{"subtype":"onchain perpetual and spot central-limit order book","tags":["perpetuals","spot","order_book","self_custody","app_specific_chain"],"chains":["Hyperliquid L1"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:hyperliquid:status"]},"outcome":{"label":"successful_established","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:hyperliquid:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Hyperliquid DEX is the flagship exchange inside HyperCore, the trading engine of Hyperliquid L1. It runs perpetual-futures and spot order books onchain, so orders, fills, margin and liquidations are recorded by the network while traders keep control of their accounts. This is not the same object as the Hyperliquid blockchain profile: the L1 also secures HyperEVM and other applications, while this report judges the exchange venue and its market design.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid:section:what_it_is:1","claim:hyperliquid:section:what_it_is:2","claim:hyperliquid:section:what_it_is:3"]},"what_happened":{"body":"The venue moved from a 2023-era perpetuals product into the dominant high-volume case in this cohort, then added spot books and a native token. HYPE launched on 2024-11-29 through a large user distribution and now links network security, fees and exchange economics. At the current replay, Hyperliquid reported about $3.07 billion of 24-hour perpetual notional, $6.90 billion of open interest and $69.68 million of spot notional. Growth did not eliminate market-design risk: validators delisted JELLY and forcibly settled positions during a March 2025 squeeze involving the shared liquidity vault.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid:section:what_happened:1","claim:hyperliquid:section:what_happened:2","claim:hyperliquid:section:what_happened:3"]},"why_this_outcome":{"body":"The best-supported explanation is vertical integration. Hyperliquid designed the chain around the exchange instead of asking a general-purpose chain to meet its latency, ordering and margin requirements. That let the product combine CEX-like books and a fast interface with self-custody and public state. A user-focused token distribution, maker rebates, builder codes and deepening liquidity reinforced the trading funnel. These mechanisms are consistent with the observed scale, but public data cannot isolate how much growth came from execution quality, incentives, the 2024 token launch, market volatility or competitors losing share.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid:section:why_this_outcome:1","claim:hyperliquid:section:why_this_outcome:2","claim:hyperliquid:section:why_this_outcome:3"]},"strategic_choices":{"body":"Management chose a purpose-built L1 and an onchain order book rather than an AMM on a neutral host chain. It distributed 31% of HYPE to prior users at launch, reserved large allocations for future rewards and contributors, and connected fees to the Assistance Fund’s automated HYPE purchases and burns. It also opened market deployment and builder-code revenue to outside teams. Those choices strengthened distribution and value capture, but they concentrate exchange, chain, validator and token risk in one stack and leave the venue responsible for interventions that a neutral settlement layer would not make.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid:section:strategic_choices:1","claim:hyperliquid:section:strategic_choices:2","claim:hyperliquid:section:strategic_choices:3","claim:hyperliquid:section:strategic_choices:4"]},"operating_model":{"body":"Traders post orders to central-limit books for perpetual and spot markets. Perpetual accounts use collateral, funding and liquidation rules; spot books settle HIP-1 assets. Fees depend on a trader’s rolling volume, makers can receive rebates and market deployers may keep part of selected fees. Validators order and finalize the exchange state, while HLP and related vaults provide market-making and liquidation capacity. Volume is not revenue and open interest is not money held for users, so each series stays separate.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid:section:operating_model:1","claim:hyperliquid:section:operating_model:2","claim:hyperliquid:section:operating_model:3"]},"token_and_value_capture":{"body":"HYPE launched on 2024-11-29 and has a one-billion-token maximum allocation in the reviewed filing. The token secures validators, pays certain network costs and can affect trading fees. Exchange fees routed to the Assistance Fund are converted into HYPE and burned; other fee shares can reach HLP, makers or market deployers. That is real protocol-linked demand, but HYPE is not an equity claim, and gross buybacks do not equal profit after incentives, vault risk, operating cost or token emissions.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid:section:token_and_value_capture:1","claim:hyperliquid:section:token_and_value_capture:2","claim:hyperliquid:section:token_and_value_capture:3"]},"counterfactual":{"body":"A neutral rollup or app deployment could have reduced the concentration created by one team’s chain, venue and frontend, but it likely would have sacrificed the execution control that made the product competitive. Earlier market-specific open-interest caps and tighter shared-vault limits might have reduced the JELLY intervention risk. The evidence cannot show whether those controls would have slowed growth or prevented the squeeze, so this is a bounded alternative, not a claim that one design guarantees safety.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid:section:counterfactual:1","claim:hyperliquid:section:counterfactual:2","claim:hyperliquid:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The principal risks are concentrated governance of a systemically important venue, shared-vault exposure, oracle and thin-market manipulation, derivatives regulation, and competition from other fast perpetual exchanges. The JELLY decision protected the vault but showed that validators can intervene in listed markets. Public sources do not provide audited exchange profit, complete validator ownership, retained-trader cohorts or jurisdiction-by-jurisdiction eligibility. Those gaps prevent a full decentralization, profitability or customer-quality conclusion.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid:section:risks_and_unknowns:1","claim:hyperliquid:section:risks_and_unknowns:2","claim:hyperliquid:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Hyperliquid began as a specialist perpetuals venue, expanded into spot markets and then launched HYPE in November 2024. The exchange’s volume, open interest and fee base grew into category leadership, while HyperEVM broadened the surrounding chain. March 2025 was the important stress test: the JELLY squeeze led to an emergency delisting and forced settlement rather than a normal market close. By 2026-08-03 the venue remained active at large scale, so the lifecycle call is successful and established, with governance maturity still being tested.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid:section:lifecycle:1","claim:hyperliquid:section:lifecycle:2","claim:hyperliquid:section:lifecycle:3"]},"outlook_and_watch":{"body":"The base case is continued category leadership, but not an uncontested monopoly. Watch perpetual notional and open interest together, spot growth separately, 30-day fees and revenue, Assistance Fund burns, validator concentration and the frequency of emergency market actions. A healthy outcome would pair durable volume with fewer discretionary interventions and broader validator control. Falling share, repeated vault losses or a widening gap between token emissions and fee-funded burns would weaken the call.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid:section:outlook_and_watch:1","claim:hyperliquid:section:outlook_and_watch:2","claim:hyperliquid:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:hyperliquid:perp-notional-24h:2026-08-03","dimension":"derivatives_notional","label":"Perpetual notional volume, 24h","value":3070990826,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"protocol-reported rolling 24 hours"},"as_of":"2026-08-03","method":"Sum of dayNtlVlm across metaAndAssetCtxs perpetual rows.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:hyperliquid:metric:perp-notional-24h"],"quality_flags":["notional_not_revenue","not_unique_users"]},{"id":"metric:hyperliquid:perp-open-interest:2026-08-03","dimension":"derivatives_notional","label":"Perpetual open interest","value":6900854751,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported latest point"},"as_of":"2026-08-03","method":"Sum of openInterest multiplied by markPx across perpetual rows.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:hyperliquid:metric:perp-open-interest"],"quality_flags":["open_interest_not_customer_assets","mark_price_sensitive"]},{"id":"metric:hyperliquid:spot-notional-24h:2026-08-03","dimension":"spot_volume","label":"Spot notional volume, 24h","value":69679924,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"protocol-reported rolling 24 hours"},"as_of":"2026-08-03","method":"Sum of dayNtlVlm across spotMetaAndAssetCtxs rows.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:hyperliquid:metric:spot-notional-24h"],"quality_flags":["not_unique_users","separate_from_perpetuals"]},{"id":"metric:hyperliquid:fees-30d:2026-08-03","dimension":"fees","label":"Protocol fees, 30d","value":49423726,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama total30d from the Hyperliquid dailyFees adapter.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:hyperliquid:metric:fees-30d"],"quality_flags":["fees_not_profit"]},{"id":"metric:hyperliquid:revenue-30d:2026-08-03","dimension":"protocol_revenue","label":"Protocol revenue, 30d","value":34496631,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama total30d from the Hyperliquid dailyRevenue adapter.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:hyperliquid:metric:revenue-30d"],"quality_flags":["adapter_definition","not_audited_profit"]}],"events":[{"id":"event:hyperliquid:hype-genesis","type":"token_launch","date":"2024-11-29","description":"HYPE launched through the Genesis distribution on 2024-11-29.","claim_ids":["claim:hyperliquid:event:hype-genesis"]},{"id":"event:hyperliquid:jelly-intervention","type":"market_intervention","date":"2025-03-26","description":"Validators delisted JELLY and forcibly settled positions during a shared-vault squeeze.","claim_ids":["claim:hyperliquid:event:jelly-intervention"]}],"sources":[{"id":"source:hyperliquid:overview","title":"Hyperliquid 101","url":"https://hyperliquid.gitbook.io/hyperliquid-docs/about-hyperliquid/hyperliquid-101-for-non-crypto-audiences","publisher":"Hyperliquid","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Current operator description of the chain, flagship exchange, HYPE uses and builder-code distribution.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:hyperliquid:fees","title":"Hyperliquid trading fees","url":"https://hyperliquid.gitbook.io/hyperliquid-docs/trading/fees","publisher":"Hyperliquid","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Current fee tiers, maker rebates, deployer share and Assistance Fund burn description.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:hyperliquid:staking","title":"Hyperliquid staking","url":"https://hyperliquid.gitbook.io/hyperliquid-docs/hypercore/staking","publisher":"Hyperliquid","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Delegated-proof-of-stake mechanics, validator self-delegation and reward rules.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:hyperliquid:api-docs","title":"Hyperliquid info endpoint","url":"https://hyperliquid.gitbook.io/hyperliquid-docs/for-developers/api/info-endpoint","publisher":"Hyperliquid","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Definitions for metaAndAssetCtxs and spotMetaAndAssetCtxs responses.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:hyperliquid:api","title":"Hyperliquid protocol API","url":"https://api.hyperliquid.xyz/info","publisher":"Hyperliquid","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"POST responses replayed for perpetual and spot market contexts during the observation window.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:hyperliquid:hip1","title":"HIP-1 native token standard","url":"https://hyperliquid.gitbook.io/hyperliquid-docs/hyperliquid-improvement-proposals-hips/hip-1-native-token-standard","publisher":"Hyperliquid","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Native token, spot-book deployment, deployer fee and burn mechanics.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:hyperliquid:sec-filing","title":"21Shares Hyperliquid ETF registration statement","url":"https://www.sec.gov/Archives/edgar/data/2078856/000119312526234992/d50758ds1.htm","publisher":"U.S. Securities and Exchange Commission","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"A","role":"independent","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Filed HYPE launch date, supply allocation, disclosed uses and vesting description.","direct_http_status":403,"access_method":"indexed_browser_snapshot"},{"id":"source:hyperliquid:jelly","title":"Hyperliquid delists JELLY after vault squeeze","url":"https://www.coindesk.com/markets/2025/03/26/hyperliquid-delists-jellyjelly-after-vault-squeezed-in-usd13m-tussle","publisher":"CoinDesk","published_at":"2025-03-26","accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Independent description of the JELLY position, validator delisting and forced settlement.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:hyperliquid:fees-api","title":"Hyperliquid fees API","url":"https://api.llama.fi/summary/fees/hyperliquid?dataType=dailyFees","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"total24h, total7d, total30d and totalAllTime returned by the fee adapter.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:hyperliquid:revenue-api","title":"Hyperliquid protocol revenue API","url":"https://api.llama.fi/summary/fees/hyperliquid?dataType=dailyRevenue","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"total24h, total7d, total30d and totalAllTime returned by the revenue adapter.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:hyperliquid:spot-api","title":"Hyperliquid spot-volume API","url":"https://api.llama.fi/summary/dexs/hyperliquid?dataType=dailyVolume","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Separately scoped spot-volume adapter used as a cross-check, not added to protocol API totals.","direct_http_status":200,"access_method":"direct_http"}],"claims":[{"id":"claim:hyperliquid:status","field_path":"status.operating_state","assertion":"Hyperliquid DEX was operating at the review date.","value":"operating","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:api","source:hyperliquid:fees-api"],"evidence_locator":"Current market-context responses and current fee-adapter observations show active trading.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:outcome","field_path":"outcome.label","assertion":"Hyperliquid DEX is classified successful established as of 2026-08-03.","value":"successful_established","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:hyperliquid:api","source:hyperliquid:fees-api","source:hyperliquid:revenue-api","source:hyperliquid:overview","source:hyperliquid:jelly"],"evidence_locator":"Current scale, documented product mechanics, sustained fee production and the material 2025 intervention are considered together.","support_direction":"supports","note":"Analyst lifecycle classification; observed activity and events do not prove one exclusive cause.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"Hyperliquid DEX operates perpetual and spot order books inside HyperCore.","value":"Hyperliquid DEX operates perpetual and spot order books inside HyperCore.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:overview","source:hyperliquid:api-docs"],"evidence_locator":"Operator product description and API market-context definitions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"The DEX is a venue on Hyperliquid L1, not the whole blockchain or HyperEVM ecosystem.","value":"The DEX is a venue on Hyperliquid L1, not the whole blockchain or HyperEVM ecosystem.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:overview","source:hyperliquid:hip1"],"evidence_locator":"The operator separates flagship exchange applications from the wider chain and token standard.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body","assertion":"Orders, fills and liquidations are represented as onchain exchange activity.","value":"Orders, fills and liquidations are represented as onchain exchange activity.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:overview","source:hyperliquid:api-docs"],"evidence_locator":"Current architecture description and market-context schema.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"HYPE launched through the Genesis distribution on 2024-11-29.","value":"HYPE launched through the Genesis distribution on 2024-11-29.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:sec-filing"],"evidence_locator":"SEC-filed registration statement describing the launch and distribution.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"The current protocol API showed multi-billion-dollar daily perpetual notional and open interest.","value":"The current protocol API showed multi-billion-dollar daily perpetual notional and open interest.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:api","source:hyperliquid:api-docs"],"evidence_locator":"Replayed metaAndAssetCtxs response and field definitions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:what_happened:3","field_path":"analysis.sections.what_happened.body","assertion":"Validators delisted JELLY and forcibly settled positions during the March 2025 squeeze.","value":"Validators delisted JELLY and forcibly settled positions during the March 2025 squeeze.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:jelly"],"evidence_locator":"Independent event report dated 2025-03-26.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Purpose-built exchange execution reduced the product constraints of deploying a matching engine on an unrelated chain.","value":"Purpose-built exchange execution reduced the product constraints of deploying a matching engine on an unrelated chain.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:hyperliquid:overview","source:hyperliquid:api-docs"],"evidence_locator":"Documented integrated stack; causal implication is analyst synthesis.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"Maker rebates, builder economics and HYPE distribution created acquisition and retention incentives around the venue.","value":"Maker rebates, builder economics and HYPE distribution created acquisition and retention incentives around the venue.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:hyperliquid:fees","source:hyperliquid:overview","source:hyperliquid:sec-filing"],"evidence_locator":"Documented fee tiers, builder codes and token distribution.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body","assertion":"Public evidence does not identify one exclusive cause for Hyperliquid growth.","value":"Public evidence does not identify one exclusive cause for Hyperliquid growth.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:hyperliquid:api","source:hyperliquid:fees-api","source:hyperliquid:overview"],"evidence_locator":"Reviewed sources measure outcomes and mechanisms but do not estimate causal contribution.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"Hyperliquid vertically integrated the venue with its own exchange-optimized L1.","value":"Hyperliquid vertically integrated the venue with its own exchange-optimized L1.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:overview","source:hyperliquid:staking"],"evidence_locator":"Current operator architecture and security model.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"The HYPE launch allocated 31% to prior users and reserved additional supply for rewards and contributors.","value":"The HYPE launch allocated 31% to prior users and reserved additional supply for rewards and contributors.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:sec-filing"],"evidence_locator":"Filed token allocation and vesting description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body","assertion":"Trading-fee flows include automated HYPE purchases and burns through the Assistance Fund.","value":"Trading-fee flows include automated HYPE purchases and burns through the Assistance Fund.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:fees"],"evidence_locator":"Current fee allocation documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:strategic_choices:4","field_path":"analysis.sections.strategic_choices.body","assertion":"Vertical integration increases the consequence of validator, venue or token-policy errors affecting the same ecosystem.","value":"Vertical integration increases the consequence of validator, venue or token-policy errors affecting the same ecosystem.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:hyperliquid:jelly","source:hyperliquid:staking","source:hyperliquid:fees"],"evidence_locator":"Observed intervention and documented shared security/economic stack.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"The venue uses separate perpetual and spot books with a shared fee-tier calculation.","value":"The venue uses separate perpetual and spot books with a shared fee-tier calculation.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:fees","source:hyperliquid:api-docs"],"evidence_locator":"Current fee rules and separate API contexts.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"Validators finalize HyperCore state and delegated HYPE secures the network.","value":"Validators finalize HyperCore state and delegated HYPE secures the network.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:staking"],"evidence_locator":"Current validator and staking documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:operating_model:3","field_path":"analysis.sections.operating_model.body","assertion":"Market deployers may retain part of selected spot or HIP-3 fees.","value":"Market deployers may retain part of selected spot or HIP-3 fees.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:fees","source:hyperliquid:hip1"],"evidence_locator":"Current deployer-fee rules.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"HYPE has a disclosed maximum allocation of one billion tokens and launched on 2024-11-29.","value":"HYPE has a disclosed maximum allocation of one billion tokens and launched on 2024-11-29.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:sec-filing"],"evidence_locator":"Filed launch and supply description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"HYPE is used for staking, network costs and trading-fee benefits.","value":"HYPE is used for staking, network costs and trading-fee benefits.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:overview","source:hyperliquid:staking","source:hyperliquid:fees"],"evidence_locator":"Current utility and fee documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Assistance Fund purchases and burns create protocol-linked demand but do not give holders an ownership claim.","value":"Assistance Fund purchases and burns create protocol-linked demand but do not give holders an ownership claim.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:hyperliquid:fees","source:hyperliquid:sec-filing"],"evidence_locator":"Fee mechanism read with the filed token-rights disclosure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"A neutral host chain would trade execution control for lower single-stack concentration.","value":"A neutral host chain would trade execution control for lower single-stack concentration.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:hyperliquid:overview","source:hyperliquid:staking"],"evidence_locator":"Documented integrated architecture used to bound the alternative.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"Tighter market and vault limits before March 2025 could plausibly have reduced JELLY exposure.","value":"Tighter market and vault limits before March 2025 could plausibly have reduced JELLY exposure.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:hyperliquid:jelly"],"evidence_locator":"Incident mechanics support the direction but not a quantified avoided loss.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body","assertion":"Public evidence cannot establish the growth cost of stricter pre-incident controls.","value":"Public evidence cannot establish the growth cost of stricter pre-incident controls.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:hyperliquid:jelly","source:hyperliquid:api"],"evidence_locator":"No reviewed source estimates the counterfactual adoption effect.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"The JELLY response demonstrates that validator intervention is a live exchange-governance risk.","value":"The JELLY response demonstrates that validator intervention is a live exchange-governance risk.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:jelly","source:hyperliquid:staking"],"evidence_locator":"Independent incident report read with the validator model.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Leveraged markets remain exposed to thin-market, oracle, liquidation and shared-vault stress.","value":"Leveraged markets remain exposed to thin-market, oracle, liquidation and shared-vault stress.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:hyperliquid:jelly","source:hyperliquid:api-docs"],"evidence_locator":"Observed squeeze and current market data fields.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Audited profit, retained traders and complete validator control relationships remain unknown.","value":"Audited profit, retained traders and complete validator control relationships remain unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:hyperliquid:api","source:hyperliquid:fees-api","source:hyperliquid:staking"],"evidence_locator":"Reviewed public sources do not publish these fields.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"The venue expanded from perpetuals into spot and a broader chain ecosystem.","value":"The venue expanded from perpetuals into spot and a broader chain ecosystem.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:overview","source:hyperliquid:hip1"],"evidence_locator":"Current product history and native spot-token standard.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"The HYPE launch materially connected exchange activity to network security and token economics.","value":"The HYPE launch materially connected exchange activity to network security and token economics.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:sec-filing","source:hyperliquid:fees","source:hyperliquid:staking"],"evidence_locator":"Launch, utility and fee documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body","assertion":"Current activity after the JELLY intervention supports an established rather than failed lifecycle call.","value":"Current activity after the JELLY intervention supports an established rather than failed lifecycle call.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:hyperliquid:api","source:hyperliquid:fees-api","source:hyperliquid:jelly"],"evidence_locator":"Current observations considered after the dated stress event.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Perpetual notional, open interest and spot volume should be monitored as separate demand signals.","value":"Perpetual notional, open interest and spot volume should be monitored as separate demand signals.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:api","source:hyperliquid:api-docs","source:hyperliquid:spot-api"],"evidence_locator":"Current separately scoped market series.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Fee-funded burns should be compared with token releases and incentives rather than read in isolation.","value":"Fee-funded burns should be compared with token releases and incentives rather than read in isolation.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:hyperliquid:fees","source:hyperliquid:sec-filing"],"evidence_locator":"Current burn mechanism and disclosed allocations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Repeated emergency interventions or shared-vault losses would weaken the established-success call.","value":"Repeated emergency interventions or shared-vault losses would weaken the established-success call.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:hyperliquid:jelly"],"evidence_locator":"The 2025 event defines a measurable governance and risk-control watch signal.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:metric:perp-notional-24h","field_path":"metrics[metric:hyperliquid:perp-notional-24h:2026-08-03].value","assertion":"Perpetual notional volume, 24h was 3070990826 USD for the stated scope and window.","value":3070990826,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:api"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:metric:perp-open-interest","field_path":"metrics[metric:hyperliquid:perp-open-interest:2026-08-03].value","assertion":"Perpetual open interest was 6900854751 USD for the stated scope and window.","value":6900854751,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:api"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:metric:spot-notional-24h","field_path":"metrics[metric:hyperliquid:spot-notional-24h:2026-08-03].value","assertion":"Spot notional volume, 24h was 69679924 USD for the stated scope and window.","value":69679924,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:api"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:metric:fees-30d","field_path":"metrics[metric:hyperliquid:fees-30d:2026-08-03].value","assertion":"Protocol fees, 30d was 49423726 USD for the stated scope and window.","value":49423726,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:fees-api"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:metric:revenue-30d","field_path":"metrics[metric:hyperliquid:revenue-30d:2026-08-03].value","assertion":"Protocol revenue, 30d was 34496631 USD for the stated scope and window.","value":34496631,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:revenue-api"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:event:hype-genesis","field_path":"events[event:hyperliquid:hype-genesis]","assertion":"HYPE launched through the Genesis distribution on 2024-11-29.","value":"2024-11-29","as_of":"2024-11-29","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:sec-filing"],"evidence_locator":"Filed launch description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:hyperliquid:event:jelly-intervention","field_path":"events[event:hyperliquid:jelly-intervention]","assertion":"Validators delisted JELLY and forcibly settled positions during a shared-vault squeeze.","value":"2025-03-26","as_of":"2025-03-26","confidence":"high","kind":"fact","source_ids":["source:hyperliquid:jelly"],"evidence_locator":"Independent dated report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T18:58:00Z","next_review_at":"2026-08-10T18:58:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["Unique retained traders","Audited operating profit","Complete validator beneficial ownership","Jurisdiction-by-jurisdiction derivatives eligibility"]},"extensions":{"legacy_origin":"successful_exchanges","observation_window":{"started_at":"2026-08-03T18:53:00Z","completed_at":"2026-08-03T18:58:00Z"},"explicit_unknowns":["Unique and retained traders across linked accounts are not published in the reviewed sources.","Complete validator ownership and coordinated-control relationships are not established by public labels.","Audited exchange-level expenses, treasury runway and net profit are not public.","The long-run effect of discretionary validator interventions on market-maker confidence is not measurable yet."],"identity_boundary":"This profile covers the Hyperliquid DEX running in HyperCore. The Hyperliquid L1 and HyperEVM are separate blockchain surfaces and have their own blockchain analysis.","methodology_notes":["Every material field is attached to atomic pending claims; a person must review those claims before the report can be published.","Routed volume is not additive to underlying DEX volume, notional is not revenue, TVL is not market depth, fees are not profit, and token price is not product success.","Documented decisions, observed outcomes, analyst inferences and unresolved unknowns are kept separate.","Perpetual notional and open interest come from Hyperliquid market-context responses; the spot series is kept separate.","Protocol fee and revenue adapters do not establish audited company profit or a legal right for HYPE holders."]}}', '{"kind":"dex","slug":"hyperliquid","lifecycle":"successful","operating_model":"Onchain perpetual and spot central-limit order books inside HyperCore.","product_cohort":"perpetual_and_spot_orderbook","custody_model":"non_custodial","primary_chain":"Hyperliquid L1","chains":["Hyperliquid L1"],"token_status":"launched","token_symbol":"HYPE","token_launch_date":"2024-11-29","token_launch_timing":"post_product","token_strategy":"network_security_costs_fee_discounts_and_fee_funded_burns","token_source_url":"https://www.sec.gov/Archives/edgar/data/2078856/000119312526234992/d50758ds1.htm","metric_type":"perpetual_notional_volume_24h","metric_unit":"usd","metric_window":"rolling_24h","metric_as_of":"2026-08-03","metric_observed_at":"2026-08-03T18:53:00Z","comparability_key":"dex|perpetual_orderbook|perpetual_notional_volume_24h|usd|rolling_24h","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"This profile covers the Hyperliquid DEX running in HyperCore. The Hyperliquid L1 and HyperEVM are separate blockchain surfaces and have their own blockchain analysis.","metric_replayed_at":"2026-08-03T18:53:00Z","source_count":11},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _dex_wave_f_profiles_0083 (
  target_table, slug, canonical_profile, feature
) VALUES ('successful_exchanges', 'raydium', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"dex:raydium","type":"dex","slug":"raydium","name":"Raydium","aliases":[]},"classification":{"subtype":"Solana spot AMM and token-launch liquidity suite","tags":["spot_amm","concentrated_liquidity","token_launches","single_chain"],"chains":["Solana"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:raydium:status"]},"outcome":{"label":"successful_cyclical","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:raydium:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Raydium is a non-custodial set of Solana programs for spot swaps, liquidity pools and token launches. Its live pool families include the original AMM v4, constant-product CPMM and concentrated-liquidity CLMM, while LaunchLab moves tokens from bonding curves into post-launch pools. The Raydium web app also links to perpetual trading powered by Orderly Network, but that external execution is not counted as Raydium DEX activity in this report.","as_of":"2026-08-03","claim_ids":["claim:raydium:section:what_it_is:1","claim:raydium:section:what_it_is:2","claim:raydium:section:what_it_is:3"]},"what_happened":{"body":"Raydium launched in 2021 as a Solana AMM that also shared liquidity with an order book. It survived the FTX/Serum break by moving away from the compromised Serum path and now runs its pool curves directly; current docs say the OpenBook integration is deactivated. A December 2022 admin-key compromise drained roughly $4.4 million from eight pools and led to multisig and operating-control changes. Raydium later added concentrated liquidity, a newer CPMM default and LaunchLab. At the current replay it recorded $45.01 million of 24-hour and $2.13 billion of 30-day spot volume with about $815.68 million of TVL.","as_of":"2026-08-03","claim_ids":["claim:raydium:section:what_happened:1","claim:raydium:section:what_happened:2","claim:raydium:section:what_happened:3"]},"why_this_outcome":{"body":"Raydium became infrastructure, not merely a destination website. Solana wallets, Jupiter and bots can use its pools as execution inventory, giving the protocol distribution wherever Solana trading occurs. Multiple pool designs serve both simple token pairs and capital-efficient markets, while LaunchLab connects primary token issuance to secondary liquidity. That combination explains why Raydium remained important after Serum and after competitors launched. The trade-off is strong dependence on Solana’s token-launch and speculative cycles; present activity does not prove stable recurring demand from the same traders.","as_of":"2026-08-03","claim_ids":["claim:raydium:section:why_this_outcome:1","claim:raydium:section:why_this_outcome:2","claim:raydium:section:why_this_outcome:3"]},"strategic_choices":{"body":"Raydium chose to remain Solana-native and composable with routers rather than expand its own pools across chains. It kept older AMM v4 pools operating while steering new deployments toward CPMM and CLMM, reducing forced migration but leaving several program generations to maintain. After losing the automatic Pump.fun graduation funnel to PumpSwap, it launched its own configurable issuance stack through LaunchLab. It also directs 12% of pool trading fees to RAY buybacks. These moves protect distribution and token demand, but add version, launch-market and single-chain concentration.","as_of":"2026-08-03","claim_ids":["claim:raydium:section:strategic_choices:1","claim:raydium:section:strategic_choices:2","claim:raydium:section:strategic_choices:3","claim:raydium:section:strategic_choices:4"]},"operating_model":{"body":"Liquidity providers deposit token pairs into AMM pools and earn their share of swap fees while bearing inventory, price and smart-contract risk. CPMM uses full-range constant-product liquidity; CLMM lets providers concentrate liquidity in selected price ranges; older AMM v4 pools remain operational. Routers choose among these pools, and LaunchLab graduates bonding-curve assets into a post-launch pool. Fee rates and destinations vary by program and configuration, so one blended percentage would be misleading.","as_of":"2026-08-03","claim_ids":["claim:raydium:section:operating_model:1","claim:raydium:section:operating_model:2","claim:raydium:section:operating_model:3"]},"token_and_value_capture":{"body":"RAY launched with the early protocol era and remains the exchange token, but reviewed official pages do not establish an exact launch day. The clearest current value-capture mechanism is the buyback: 12% of trading fees from the documented pool families purchases RAY into a public protocol-controlled address. CPMM and CLMM also route a treasury share while most fees stay with liquidity providers. Buybacks create demand, but bought tokens held by the protocol are not automatically burned, and gross fee allocation is not the same as earnings available to a token holder.","as_of":"2026-08-03","claim_ids":["claim:raydium:section:token_and_value_capture:1","claim:raydium:section:token_and_value_capture:2","claim:raydium:section:token_and_value_capture:3"]},"counterfactual":{"body":"A multi-chain deployment strategy could have reduced Solana dependence, but it also would have fragmented engineering attention and liquidity away from the ecosystem where Raydium had distribution. Faster removal of single-key administrative control before December 2022 could plausibly have prevented or limited the pool drain. A cleaner forced migration from old programs might reduce maintenance burden, yet it could strand liquidity and integrations. Public evidence cannot quantify those adoption and security trade-offs.","as_of":"2026-08-03","claim_ids":["claim:raydium:section:counterfactual:1","claim:raydium:section:counterfactual:2","claim:raydium:section:counterfactual:3"]},"risks_and_unknowns":{"body":"Raydium is exposed to Solana outages and market cycles, smart-contract and authority risk, fragmented liquidity across pool versions, adverse token launches and fast-moving AMM competition. LaunchLab brings distribution but also places low-quality token issuance next to the exchange brand. The 2022 loss shows that correct program code is not enough when keys and operations fail. Unique traders, launch retention, net profit and the share of volume driven by temporary speculation remain unknown.","as_of":"2026-08-03","claim_ids":["claim:raydium:section:risks_and_unknowns:1","claim:raydium:section:risks_and_unknowns:2","claim:raydium:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Raydium’s first phase was an AMM tied to Serum’s order book. The FTX collapse forced Solana liquidity to move to community-controlled alternatives, and Raydium eventually deactivated the order-book integration. The December 2022 admin-key exploit was the major security break, followed by stronger authority controls. CPMM, CLMM and LaunchLab then widened the product. Current activity is far below January 2025’s TVL high but remains substantial, so this is a durable success with pronounced cycle exposure, not a dying venue.","as_of":"2026-08-03","claim_ids":["claim:raydium:section:lifecycle:1","claim:raydium:section:lifecycle:2","claim:raydium:section:lifecycle:3"]},"outlook_and_watch":{"body":"The most useful watch is whether Raydium remains essential after each launch cycle cools. Track 30-day spot volume, TVL, fee revenue, RAY purchased, pool-version concentration and the share of launches that keep liquidity after graduation. Continued router usage and fee production would support the base case. A sustained migration of wallet flow and token graduations to competing venues, or another authority incident, would weaken the success call even if short-lived volume spikes continue.","as_of":"2026-08-03","claim_ids":["claim:raydium:section:outlook_and_watch:1","claim:raydium:section:outlook_and_watch:2","claim:raydium:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:raydium:spot-volume-24h:2026-08-03","dimension":"spot_volume","label":"Spot volume, 24h","value":45008368,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 24 hours"},"as_of":"2026-08-03","method":"DefiLlama total24h from the Raydium dailyVolume adapter.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:raydium:metric:spot-volume-24h"],"quality_flags":["routed_flow_possible","not_unique_users"]},{"id":"metric:raydium:spot-volume-30d:2026-08-03","dimension":"spot_volume","label":"Spot volume, 30d","value":2132161158,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama total30d from the Raydium dailyVolume adapter.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:raydium:metric:spot-volume-30d"],"quality_flags":["routed_flow_possible","not_unique_users"]},{"id":"metric:raydium:tvl-latest:2026-08-03","dimension":"tvl","label":"Protocol TVL","value":815678078,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported latest point"},"as_of":"2026-08-03","method":"Latest totalLiquidityUSD in the Raydium protocol response.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:raydium:metric:tvl-latest"],"quality_flags":["tvl_not_market_depth","staked_token_scope_separate"]},{"id":"metric:raydium:fees-30d:2026-08-03","dimension":"fees","label":"Protocol fees, 30d","value":3025592,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama total30d from the Raydium dailyFees adapter.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:raydium:metric:fees-30d"],"quality_flags":["fees_not_profit"]},{"id":"metric:raydium:revenue-30d:2026-08-03","dimension":"protocol_revenue","label":"Protocol revenue, 30d","value":463295,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama total30d from the Raydium dailyRevenue adapter.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:raydium:metric:revenue-30d"],"quality_flags":["adapter_definition","not_audited_profit"]}],"events":[{"id":"event:raydium:admin-key-exploit","type":"exploit","date":"2022-12-16","description":"A compromised Raydium admin account drained about $4.4 million from eight pools.","claim_ids":["claim:raydium:event:admin-key-exploit"]}],"sources":[{"id":"source:raydium:overview","title":"What is Raydium","url":"https://docs.raydium.io/introduction/what-is-raydium","publisher":"Raydium","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Current product surfaces, protocol/interface distinction, users and routing relationships.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:raydium:versions","title":"Raydium versions and migration","url":"https://docs.raydium.io/protocol-overview/versions-and-migration","publisher":"Raydium","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Current and legacy program status across AMM, CPMM, CLMM, farms and LaunchLab.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:raydium:fees","title":"Raydium protocol fees","url":"https://docs.raydium.io/ray/protocol-fees","publish