,"archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"total30d from the current dailyRevenue adapter.","direct_http_status":200,"access_method":"direct_http"}],"claims":[{"id":"claim:raydium:status","field_path":"status.operating_state","assertion":"Raydium was operating at the review date.","value":"operating","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:overview","source:raydium:volume","source:raydium:tvl"],"evidence_locator":"Current operator documentation and live independent volume and TVL observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:outcome","field_path":"outcome.label","assertion":"Raydium is classified successful cyclical as of 2026-08-03.","value":"successful_cyclical","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:raydium:volume","source:raydium:tvl","source:raydium:fees-api","source:raydium:overview","source:raydium:security"],"evidence_locator":"Current scale, durable Solana integrations, fee production and incident history support a successful but cyclical call.","support_direction":"supports","note":"Analyst lifecycle classification; observed activity and events do not prove one exclusive cause.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"Raydium operates non-custodial AMM, CPMM, CLMM and LaunchLab programs on Solana.","value":"Raydium operates non-custodial AMM, CPMM, CLMM and LaunchLab programs on Solana.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:overview","source:raydium:versions"],"evidence_locator":"Current product and version documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"Raydium Perps is an interface surface powered by Orderly Network rather than a Raydium-native derivatives venue.","value":"Raydium Perps is an interface surface powered by Orderly Network rather than a Raydium-native derivatives venue.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:overview"],"evidence_locator":"Current operator product boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body","assertion":"Wallets and aggregators can route through Raydium pools without the trader visiting raydium.io.","value":"Wallets and aggregators can route through Raydium pools without the trader visiting raydium.io.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:overview"],"evidence_locator":"Current distribution and integration description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"Raydium began in 2021 and its former order-book integration is no longer active.","value":"Raydium began in 2021 and its former order-book integration is no longer active.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:overview","source:raydium:versions"],"evidence_locator":"Current operator history and version status.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"A compromised admin account drained about $4.4 million from eight pools in December 2022.","value":"A compromised admin account drained about $4.4 million from eight pools in December 2022.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:postmortem","source:raydium:security"],"evidence_locator":"Dated operator postmortem and current incident summary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:what_happened:3","field_path":"analysis.sections.what_happened.body","assertion":"Current independent adapters show material spot volume and TVL well below the historical TVL peak.","value":"Current independent adapters show material spot volume and TVL well below the historical TVL peak.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:volume","source:raydium:tvl"],"evidence_locator":"Replayed current and historical provider series.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Aggregator and wallet routing give Raydium distribution beyond its own interface.","value":"Aggregator and wallet routing give Raydium distribution beyond its own interface.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:raydium:overview","source:raydium:volume"],"evidence_locator":"Documented integration pattern and observed pool volume.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"Multiple pool designs and LaunchLab connect trading, liquidity provision and token issuance.","value":"Multiple pool designs and LaunchLab connect trading, liquidity provision and token issuance.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:versions","source:raydium:launchlab"],"evidence_locator":"Current product mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body","assertion":"Public data does not establish how much current volume is repeat demand versus launch-cycle activity.","value":"Public data does not establish how much current volume is repeat demand versus launch-cycle activity.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:raydium:volume","source:raydium:launchlab"],"evidence_locator":"Volume series and launch mechanics do not provide deduplicated cohorts.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"Raydium stayed concentrated on Solana and integrated with its routing layer.","value":"Raydium stayed concentrated on Solana and integrated with its routing layer.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:overview"],"evidence_locator":"Current chain and integration description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"Raydium keeps AMM v4 live while recommending CPMM or CLMM for newer use cases.","value":"Raydium keeps AMM v4 live while recommending CPMM or CLMM for newer use cases.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:versions"],"evidence_locator":"Current migration and version policy.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body","assertion":"LaunchLab internalized token issuance and pool graduation as a Raydium product.","value":"LaunchLab internalized token issuance and pool graduation as a Raydium product.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:launchlab"],"evidence_locator":"Current LaunchLab workflow.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:strategic_choices:4","field_path":"analysis.sections.strategic_choices.body","assertion":"Twelve percent of pool trading fees funds RAY purchases.","value":"Twelve percent of pool trading fees funds RAY purchases.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:buybacks","source:raydium:fees"],"evidence_locator":"Current fee split and buyback documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"Raydium pool families use different liquidity and fee mechanics.","value":"Raydium pool families use different liquidity and fee mechanics.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:versions","source:raydium:fees"],"evidence_locator":"Current program status and fee schedules.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"Liquidity providers supply inventory and receive pool-specific fee shares.","value":"Liquidity providers supply inventory and receive pool-specific fee shares.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:fees"],"evidence_locator":"Current swap-fee destinations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:operating_model:3","field_path":"analysis.sections.operating_model.body","assertion":"LaunchLab can graduate bonding-curve liquidity into Raydium CPMM pools.","value":"LaunchLab can graduate bonding-curve liquidity into Raydium CPMM pools.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:launchlab"],"evidence_locator":"Current graduation flow.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"RAY was already part of the protocol during its 2021 launch era, but the reviewed sources do not establish an exact token-launch day.","value":"RAY was already part of the protocol during its 2021 launch era, but the reviewed sources do not establish an exact token-launch day.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:raydium:overview","source:raydium:buybacks"],"evidence_locator":"Current history and token mechanism with date limitation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Twelve percent of documented pool trading fees is used to buy RAY.","value":"Twelve percent of documented pool trading fees is used to buy RAY.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:buybacks","source:raydium:fees"],"evidence_locator":"Current fee split.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Protocol-held buybacks do not by themselves prove a holder cash-flow right or net deflation.","value":"Protocol-held buybacks do not by themselves prove a holder cash-flow right or net deflation.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:raydium:buybacks","source:raydium:fees-api","source:raydium:revenue-api"],"evidence_locator":"Mechanism read against scoped fee and revenue observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"Multi-chain expansion would trade Solana focus for lower chain concentration and more fragmented liquidity.","value":"Multi-chain expansion would trade Solana focus for lower chain concentration and more fragmented liquidity.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:raydium:overview","source:raydium:versions"],"evidence_locator":"Current single-chain product architecture used to bound the alternative.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"Earlier multisig controls could plausibly have reduced the December 2022 admin-key loss.","value":"Earlier multisig controls could plausibly have reduced the December 2022 admin-key loss.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:raydium:postmortem","source:raydium:security"],"evidence_locator":"The incident root cause and later mitigation support the direction.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body","assertion":"The adoption cost of forcing old pools to migrate is not published.","value":"The adoption cost of forcing old pools to migrate is not published.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:raydium:versions"],"evidence_locator":"Current coexistence policy explains the trade-off but provides no counterfactual estimate.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Single-chain dependence and several live program generations are material operating risks.","value":"Single-chain dependence and several live program generations are material operating risks.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:raydium:overview","source:raydium:versions"],"evidence_locator":"Current chain and version architecture.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"The 2022 incident was an operational key-control failure rather than a pool-math bug.","value":"The 2022 incident was an operational key-control failure rather than a pool-math bug.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:postmortem","source:raydium:security"],"evidence_locator":"Operator root-cause description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Trader retention, launch survival and audited net profit remain unknown.","value":"Trader retention, launch survival and audited net profit remain unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:raydium:volume","source:raydium:launchlab","source:raydium:revenue-api"],"evidence_locator":"Reviewed sources do not publish those fields.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"Raydium outlived its original Serum-linked architecture and now routes current swaps through AMM curves.","value":"Raydium outlived its original Serum-linked architecture and now routes current swaps through AMM curves.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:overview","source:raydium:versions"],"evidence_locator":"Current product history and version status.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"The 2022 exploit led to authority and operational-control changes.","value":"The 2022 exploit led to authority and operational-control changes.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:postmortem","source:raydium:security"],"evidence_locator":"Dated incident response and current controls summary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body","assertion":"Current TVL is about 72.5% below the adapter peak while the venue still produces material volume.","value":"Current TVL is about 72.5% below the adapter peak while the venue still produces material volume.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:tvl","source:raydium:volume"],"evidence_locator":"Historical maximum and current observations from independent adapters.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Volume, TVL, fees and buybacks should be tracked separately to test durable economics.","value":"Volume, TVL, fees and buybacks should be tracked separately to test durable economics.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:volume","source:raydium:tvl","source:raydium:fees-api","source:raydium:buybacks"],"evidence_locator":"Current independent series and token mechanism.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Post-graduation liquidity retention is a better LaunchLab health signal than launch-day turnover alone.","value":"Post-graduation liquidity retention is a better LaunchLab health signal than launch-day turnover alone.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:raydium:launchlab"],"evidence_locator":"Current launch and graduation mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Loss of router flow or another authority incident would weaken Raydium’s infrastructure advantage.","value":"Loss of router flow or another authority incident would weaken Raydium’s infrastructure advantage.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:raydium:overview","source:raydium:security"],"evidence_locator":"Documented distribution moat and incident history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:metric:spot-volume-24h","field_path":"metrics[metric:raydium:spot-volume-24h:2026-08-03].value","assertion":"Spot volume, 24h was 45008368 USD for the stated scope and window.","value":45008368,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:volume"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:metric:spot-volume-30d","field_path":"metrics[metric:raydium:spot-volume-30d:2026-08-03].value","assertion":"Spot volume, 30d was 2132161158 USD for the stated scope and window.","value":2132161158,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:volume"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:metric:tvl-latest","field_path":"metrics[metric:raydium:tvl-latest:2026-08-03].value","assertion":"Protocol TVL was 815678078 USD for the stated scope and window.","value":815678078,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:tvl"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:metric:fees-30d","field_path":"metrics[metric:raydium:fees-30d:2026-08-03].value","assertion":"Protocol fees, 30d was 3025592 USD for the stated scope and window.","value":3025592,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:fees-api"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:metric:revenue-30d","field_path":"metrics[metric:raydium:revenue-30d:2026-08-03].value","assertion":"Protocol revenue, 30d was 463295 USD for the stated scope and window.","value":463295,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:raydium:revenue-api"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:raydium:event:admin-key-exploit","field_path":"events[event:raydium:admin-key-exploit]","assertion":"A compromised Raydium admin account drained about $4.4 million from eight pools.","value":"2022-12-16","as_of":"2022-12-16","confidence":"high","kind":"fact","source_ids":["source:raydium:postmortem","source:raydium:security"],"evidence_locator":"Operator incident timeline and current incident summary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T18:58:00Z","next_review_at":"2026-08-10T18:58:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["Unique retained traders","Launch cohort retention","Audited net profit","Organic versus launch-driven volume share"]},"extensions":{"legacy_origin":"successful_exchanges","observation_window":{"started_at":"2026-08-03T18:53:00Z","completed_at":"2026-08-03T18:58:00Z"},"explicit_unknowns":["Unique and retained traders after wallet and aggregator deduplication are not public.","LaunchLab cohort survival and post-graduation liquidity retention are not published as a complete dataset.","Complete protocol expenses and net profit after incentives are not public.","The share of volume attributable to organic trading versus short-lived token launches is not established."],"identity_boundary":"This profile covers Raydium-native AMM, CLMM, CPMM and LaunchLab programs. Raydium Perps is an interface powered by Orderly Network and is not counted as Raydium-owned derivatives execution.","methodology_notes":["Every material field is attached to atomic pending claims; a person must review those claims before the report can be published.","Routed volume is not additive to underlying DEX volume, notional is not revenue, TVL is not market depth, fees are not profit, and token price is not product success.","Documented decisions, observed outcomes, analyst inferences and unresolved unknowns are kept separate.","Raydium pool volume may be routed through Jupiter or wallets; it cannot be added to aggregator-routed volume as new economic activity.","The protocol TVL adapter includes staked RAY separately from Solana pool liquidity; this profile uses the latest totalLiquidityUSD series point."]}}', '{"kind":"dex","slug":"raydium","lifecycle":"successful","operating_model":"Solana-native AMM, CPMM, CLMM and token-launch liquidity programs.","product_cohort":"single_chain_spot_amm_suite","custody_model":"non_custodial","primary_chain":"Solana","chains":["Solana"],"token_status":"launched","token_symbol":"RAY","token_launch_date":null,"token_launch_timing":"at_or_near_launch","token_strategy":"liquidity_incentives_and_fee_funded_protocol_buybacks","token_source_url":"https://docs.raydium.io/ray/ray-buybacks","metric_type":"spot_volume_24h","metric_unit":"usd","metric_window":"rolling_24h","metric_as_of":"2026-08-03","metric_observed_at":"2026-08-03T18:53:00Z","comparability_key":"dex|spot_amm|spot_volume_24h|usd|rolling_24h","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"This profile covers Raydium-native AMM, CLMM, CPMM and LaunchLab programs. Raydium Perps is an interface powered by Orderly Network and is not counted as Raydium-owned derivatives execution.","metric_replayed_at":"2026-08-03T18:53:00Z","source_count":11},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _dex_wave_f_profiles_0083 (
  target_table, slug, canonical_profile, feature
) VALUES ('mid_exchanges', 'osmosis', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"dex:osmosis","type":"dex","slug":"osmosis","name":"Osmosis DEX","aliases":["Osmosis"]},"classification":{"subtype":"sovereign cross-chain appchain DEX","tags":["spot_amm","appchain","ibc","concentrated_liquidity","governance"],"chains":["Osmosis","Cosmos IBC"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:osmosis:status"]},"outcome":{"label":"operating_middling","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:osmosis:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Osmosis is both a decentralized spot exchange and the sovereign Cosmos SDK chain that runs it. Users trade assets connected through IBC and related bridges, while liquidity providers use classic and concentrated pools. The appchain controls execution, fees, governance and validator security instead of renting those functions from another L1. That gives Osmosis unusual product control, but it also means exchange economics must help support an entire blockchain.","as_of":"2026-08-03","claim_ids":["claim:osmosis:section:what_it_is:1","claim:osmosis:section:what_it_is:2","claim:osmosis:section:what_it_is:3"]},"what_happened":{"body":"Osmosis launched in 2021 and grew into the main liquidity hub for the early IBC economy. Its TVL peaked around $1.83 billion on 2022-03-03. A June 2022 software bug let users receive excess pool shares; validators halted the chain and an estimated $5 million was taken before recoveries and foundation coverage. The broader crypto and Cosmos contraction then removed most of the capital base. By 2026-08-03 the adapter showed about $11.93 million of TVL, $696,752 of 24-hour volume and $45.16 million over 30 days.","as_of":"2026-08-03","claim_ids":["claim:osmosis:section:what_happened:1","claim:osmosis:section:what_happened:2","claim:osmosis:section:what_happened:3"]},"why_this_outcome":{"body":"Osmosis succeeded technically by specializing in interchain liquidity and by controlling the whole exchange stack. Early OSMO emissions paid users and validators to build that market. The same strategy became expensive when token prices, IBC flows and Cosmos risk appetite contracted: subsidies could attract capital, but they could not create lasting external demand. Governance has since cut recurring incentives and shifted toward taker-fee burns and revenue-based security. The venue remains useful, yet its smaller volume and fees have not restored the economic scale reached during the incentive-heavy cycle.","as_of":"2026-08-03","claim_ids":["claim:osmosis:section:why_this_outcome:1","claim:osmosis:section:why_this_outcome:2","claim:osmosis:section:why_this_outcome:3"]},"strategic_choices":{"body":"Osmosis chose a sovereign appchain rather than contracts on a larger settlement network. It used OSMO inflation for liquidity and staking, introduced concentrated liquidity, fee abstraction and protocol-owned arbitrage, and later added a taker fee. After incentives proved costly, governance moved to reduce recurring liquidity rewards and staking subsidies, increase the portion of fee-bought OSMO that is burned and lean on real revenue. These changes reduce dilution, but they also test whether liquidity and validator participation stay healthy without the original subsidy.","as_of":"2026-08-03","claim_ids":["claim:osmosis:section:strategic_choices:1","claim:osmosis:section:strategic_choices:2","claim:osmosis:section:strategic_choices:3","claim:osmosis:section:strategic_choices:4"]},"operating_model":{"body":"Osmosis validators order swaps and secure the appchain. Liquidity providers deposit assets into pools and earn swap fees; concentrated positions require active range management. The protocol collects taker fees in the incoming asset, converts part of non-OSMO revenue, and allocates OSMO between stakers and burns according to governance parameters. ProtoRev and block auctions seek additional value from arbitrage and transaction ordering. These revenue streams are different and may change through governance, so the profile does not treat one current split as permanent.","as_of":"2026-08-03","claim_ids":["claim:osmosis:section:operating_model:1","claim:osmosis:section:operating_model:2","claim:osmosis:section:operating_model:3"]},"token_and_value_capture":{"body":"OSMO launched with the network in June 2021; the reviewed material establishes the month but not an exact day, so no day is asserted. OSMO governs the chain, secures validators and has funded liquidity incentives. Taker fees now create a clearer link between exchange use and token demand through conversions, staking distributions and burns. Governance is trying to push burns above remaining emissions. That improves the design, but current 30-day revenue was only $27,762 in the replay and does not prove that fees can support security through a prolonged downturn.","as_of":"2026-08-03","claim_ids":["claim:osmosis:section:token_and_value_capture:1","claim:osmosis:section:token_and_value_capture:2","claim:osmosis:section:token_and_value_capture:3"]},"counterfactual":{"body":"Earlier reduction of broad emissions and faster concentration on fee-producing markets might have preserved more treasury value and reduced mercenary liquidity. Deploying only as contracts on another chain could have lowered validator-security cost, but Osmosis would have lost execution control and much of its appchain differentiation. More testing before the June 2022 upgrade would likely have prevented that specific pool-share bug. None of these alternatives guarantees that Cosmos-wide liquidity would have remained after the 2022 market contraction.","as_of":"2026-08-03","claim_ids":["claim:osmosis:section:counterfactual:1","claim:osmosis:section:counterfactual:2","claim:osmosis:section:counterfactual:3"]},"risks_and_unknowns":{"body":"Osmosis faces low current economic scale, dependence on IBC asset demand, validator-security cost, governance execution, bridge and interchain risk, and smart-contract or chain-upgrade failure. Concentrated liquidity adds active-management and impermanent-loss risk for providers. The current tokenomics transition may reduce dilution but could also reduce staking or liquidity if fee income is inadequate. Public data does not disclose retained traders, the subsidy mix of liquidity, complete operating expenses or validator profitability.","as_of":"2026-08-03","claim_ids":["claim:osmosis:section:risks_and_unknowns:1","claim:osmosis:section:risks_and_unknowns:2","claim:osmosis:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Osmosis moved from a 2021 launch to a rapid IBC liquidity boom, a March 2022 TVL peak and a June 2022 exploit-and-halt. Capital then contracted with the wider Cosmos and crypto cycle. The next phase has been economic repair: concentrated liquidity, taker fees, auction revenue, fewer recurring incentives and lower staking subsidies. The DEX is still operating and strategically important to IBC, but the 99.35% TVL drawdown and modest fee base make “middling” more accurate than either successful at scale or dead.","as_of":"2026-08-03","claim_ids":["claim:osmosis:section:lifecycle:1","claim:osmosis:section:lifecycle:2","claim:osmosis:section:lifecycle:3"]},"outlook_and_watch":{"body":"The base case is continued operation as a smaller interchain liquidity hub. Watch TVL and volume without renewed broad subsidies, taker-fee revenue, daily OSMO burns versus emissions, the staked share, validator concentration and IBC transfer activity. Rising fee-funded demand with stable security would support recovery. Falling stake or liquidity after subsidy cuts, governance reversals, or further loss of IBC activity would show that the appchain’s technical control is not producing sustainable economics.","as_of":"2026-08-03","claim_ids":["claim:osmosis:section:outlook_and_watch:1","claim:osmosis:section:outlook_and_watch:2","claim:osmosis:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:osmosis:spot-volume-24h:2026-08-03","dimension":"spot_volume","label":"Spot volume, 24h","value":696752,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 24 hours"},"as_of":"2026-08-03","method":"DefiLlama total24h from the Osmosis DEX dailyVolume adapter.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:osmosis:metric:spot-volume-24h"],"quality_flags":["not_unique_users"]},{"id":"metric:osmosis:spot-volume-30d:2026-08-03","dimension":"spot_volume","label":"Spot volume, 30d","value":45163607,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama total30d from the Osmosis DEX dailyVolume adapter.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:osmosis:metric:spot-volume-30d"],"quality_flags":["not_unique_users"]},{"id":"metric:osmosis:tvl-latest:2026-08-03","dimension":"tvl","label":"Protocol TVL","value":11928437,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported latest point"},"as_of":"2026-08-03","method":"Latest totalLiquidityUSD in the Osmosis DEX protocol response.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:osmosis:metric:tvl-latest"],"quality_flags":["tvl_not_market_depth"]},{"id":"metric:osmosis:tvl-peak:2022-03-03","dimension":"tvl","label":"Historical peak TVL","value":1831730122,"unit":"usd","currency":"USD","window":{"start":null,"end":"2022-03-03","definition":"historical maximum in provider series"},"as_of":"2022-03-03","method":"Maximum totalLiquidityUSD in the Osmosis DEX protocol response, dated 2022-03-03.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_