e_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:osmosis:metric:revenue-30d","field_path":"metrics[metric:osmosis:revenue-30d:2026-08-03].value","assertion":"Protocol revenue, 30d was 27762 USD for the stated scope and window.","value":27762,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:osmosis:revenue-api"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:osmosis:event:pool-share-exploit","field_path":"events[event:osmosis:pool-share-exploit]","assertion":"A pool-share calculation bug led to an estimated $5 million exploit and an emergency chain halt.","value":"2022-06-08","as_of":"2022-06-08","confidence":"high","kind":"fact","source_ids":["source:osmosis:exploit","source:osmosis:exploit-response"],"evidence_locator":"Independent incident report and community recovery recap.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T18:58:00Z","next_review_at":"2026-08-10T18:58:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["Unique retained traders","Liquidity by subsidy source","Full-cycle post-emission validator economics","Audited operating profit"]},"extensions":{"legacy_origin":"mid_exchanges","observation_window":{"started_at":"2026-08-03T18:53:00Z","completed_at":"2026-08-03T18:58:00Z"},"explicit_unknowns":["The share of current liquidity supported by incentives, protocol-owned positions or independent market makers is not public.","Unique and retained traders across IBC addresses are not available in the reviewed sources.","Validator economics after future subsidy reductions are not yet observable over a full market cycle.","The amount of Cosmos-wide activity that can return to Osmosis is not knowable from protocol design alone."],"identity_boundary":"This profile covers the Osmosis exchange and its exchange-specific appchain economics. It does not assign activity from every Cosmos SDK or IBC chain to Osmosis.","methodology_notes":["Every material field is attached to atomic pending claims; a person must review those claims before the report can be published.","Routed volume is not additive to underlying DEX volume, notional is not revenue, TVL is not market depth, fees are not profit, and token price is not product success.","Documented decisions, observed outcomes, analyst inferences and unresolved unknowns are kept separate.","Osmosis controls its own chain execution, so DEX product risk and validator-liveness risk are more tightly coupled than for a contract-only AMM.","Governance forum posts document proposals and implementation status; a proposed mechanism is not treated as completed unless the source says it passed or shipped."]}}', '{"kind":"dex","slug":"osmosis","lifecycle":"mid","operating_model":"Sovereign appchain DEX for IBC-connected spot markets and concentrated liquidity.","product_cohort":"sovereign_appchain_spot_amm","custody_model":"non_custodial","primary_chain":"Osmosis","chains":["Osmosis","Cosmos IBC"],"token_status":"launched","token_symbol":"OSMO","token_launch_date":null,"token_launch_timing":"at_or_near_launch","token_strategy":"governance_security_liquidity_incentives_and_fee_burns","token_source_url":"https://forum.osmosis.zone/t/tokenomics-roadmap/3775","metric_type":"spot_volume_24h","metric_unit":"usd","metric_window":"rolling_24h","metric_as_of":"2026-08-03","metric_observed_at":"2026-08-03T18:53:00Z","comparability_key":"dex|sovereign_appchain_spot_amm|spot_volume_24h|usd|rolling_24h","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"This profile covers the Osmosis exchange and its exchange-specific appchain economics. It does not assign activity from every Cosmos SDK or IBC chain to Osmosis.","metric_replayed_at":"2026-08-03T18:53:00Z","source_count":11},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _dex_wave_f_profiles_0083 (
  target_table, slug, canonical_profile, feature
) VALUES ('dead_exchanges', 'kyberswap', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"dex:kyberswap","type":"dex","slug":"kyberswap","name":"KyberSwap","aliases":["KyberSwap Aggregator","KyberSwap Elastic (retired pools)"]},"classification":{"subtype":"multi-chain liquidity aggregator with legacy AMM pools","tags":["aggregator","multi_chain","routing","legacy_amm","post_exploit"],"chains":["Ethereum","Arbitrum","Base","BNB Chain","Polygon","Avalanche","Optimism","Linea","Scroll","zkSync Era","additional EVM networks"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:kyberswap:status"]},"outcome":{"label":"operating_impaired_after_exploit","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:kyberswap:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"KyberSwap is now primarily a non-custodial routing service. Its aggregator compares and splits same-chain swaps across outside DEXs, private market makers, order books and Kyber sources, while the wider interface also offers limit and cross-chain flows. That current product is different from KyberSwap Elastic, the concentrated-liquidity pool system exploited in 2023. This report keeps both in one lifecycle without pretending routed liquidity belongs to KyberSwap.","as_of":"2026-08-03","claim_ids":["claim:kyberswap:section:what_it_is:1","claim:kyberswap:section:what_it_is:2","claim:kyberswap:section:what_it_is:3"]},"what_happened":{"body":"Kyber began as an onchain liquidity network and later combined aggregation with its own AMM generations. On 2023-11-22, a precision and tick-accounting flaw in Elastic pools was exploited. KyberSwap reports about $56.20 million of affected assets across 2,367 liquidity providers, including roughly $55.23 million removed from pools; about $5.7 million was recovered from front-running bots. The treasury-grant program later distributed grants covering 100% of the reference value to approved applicants. Those grants came from KyberSwap resources; they were not a full direct recovery of the stolen assets. By 2026-08-03 the aggregator showed $5.26 billion of 30-day routed volume, while the protocol TVL adapter showed only about $1.09 million of current non-staking liquidity.","as_of":"2026-08-03","claim_ids":["claim:kyberswap:section:what_happened:1","claim:kyberswap:section:what_happened:2","claim:kyberswap:section:what_happened:3","claim:kyberswap:section:what_happened:4"]},"why_this_outcome":{"body":"KyberSwap retained a useful distribution product because routing does not require it to rebuild all of the liquidity lost from Elastic. Integrating many venues lets the interface compete on execution quality while external pools carry most inventory risk. The 2023 exploit still destroyed confidence in Kyber-owned concentrated liquidity and forced the treasury to absorb compensation. The result is not dead: routed activity is real. It is impaired because the successful current surface is economically and technically different from the pool product that failed, and public evidence does not show that routing revenue rebuilt the lost capital base.","as_of":"2026-08-03","claim_ids":["claim:kyberswap:section:why_this_outcome:1","claim:kyberswap:section:why_this_outcome:2","claim:kyberswap:section:why_this_outcome:3"]},"strategic_choices":{"body":"Kyber chose both aggregation and owned concentrated-liquidity pools. The combination offered route control and fee opportunities, but it also put treasury capital and user deposits behind a more complex pool design. After the exploit, KyberSwap halted Elastic deposits, published a detailed accounting, recovered bot-held assets and funded a grant program instead of leaving approved applicants with the reference-value loss. The current strategy emphasizes aggregation, developer APIs, limit orders and cross-chain execution. That narrows capital exposure but makes distribution and execution quality more important than owned TVL.","as_of":"2026-08-03","claim_ids":["claim:kyberswap:section:strategic_choices:1","claim:kyberswap:section:strategic_choices:2","claim:kyberswap:section:strategic_choices:3"]},"operating_model":{"body":"For an aggregator swap, KyberSwap requests quotes, selects or splits a route and builds an onchain transaction that the user signs. The underlying pools or market makers provide inventory and charge their own fees; KyberSwap documentation says the default aggregator does not charge the user a separate trading fee, while integrators can configure fees. Limit orders and cross-chain products have distinct execution and risk. Legacy Elastic pools should not be treated as the liquidity behind current routed volume.","as_of":"2026-08-03","claim_ids":["claim:kyberswap:section:operating_model:1","claim:kyberswap:section:operating_model:2","claim:kyberswap:section:operating_model:3"]},"token_and_value_capture":{"body":"KNC predates the current aggregator and remains the KyberDAO governance and staking token. The reviewed DAO documentation says a portion of fees collected from KyberSwap liquidity pools is converted into KNC and paid to eligible voters, with the ratio controlled by governance. That mechanism links KNC to Kyber-owned pool activity, not automatically to every dollar routed through external DEXs. The exact present contribution of aggregator integrations, pool fees and treasury incentives to KNC demand is not publicly separated.","as_of":"2026-08-03","claim_ids":["claim:kyberswap:section:token_and_value_capture:1","claim:kyberswap:section:token_and_value_capture:2","claim:kyberswap:section:token_and_value_capture:3"]},"counterfactual":{"body":"A narrower aggregator-only strategy would have avoided exposure to the Elastic code path and the resulting treasury obligation, but it also would have given Kyber less control over liquidity and fee economics. Correct rounding direction, stronger boundary tests and adversarial testing of reinvestment logic could plausibly have prevented the specific exploit. Earlier isolation of pool versions could have reduced the blast radius. The evidence cannot show whether a safer but less ambitious product would have retained the same integrations or users.","as_of":"2026-08-03","claim_ids":["claim:kyberswap:section:counterfactual:1","claim:kyberswap:section:counterfactual:2","claim:kyberswap:section:counterfactual:3"]},"risks_and_unknowns":{"body":"KyberSwap still faces router-contract, quote, integration, MEV, external-venue and cross-chain risk. Its brand also carries the trust cost of the Elastic exploit, while the treasury absorbed grants that may affect runway. Aggregator volume can look large because it passes through hundreds of venues; it is not owned liquidity or unique demand. Direct primary-attacker recovery, non-applicant outcomes, retained traders and audited post-grant profitability remain unknown.","as_of":"2026-08-03","claim_ids":["claim:kyberswap:section:risks_and_unknowns:1","claim:kyberswap:section:risks_and_unknowns:2","claim:kyberswap:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Kyber evolved from its original liquidity network into a multi-chain aggregator plus AMM suite. Elastic added capital-efficient pools but became the decisive failure point in November 2023. Recovery and grants protected approved applicants, while the owned-pool capital base collapsed. The aggregator continued and, by the current replay, routed billions of dollars over 30 days. The correct lifecycle is therefore operating but impaired after an exploit—not dead, and not a clean success.","as_of":"2026-08-03","claim_ids":["claim:kyberswap:section:lifecycle:1","claim:kyberswap:section:lifecycle:2","claim:kyberswap:section:lifecycle:3"]},"outlook_and_watch":{"body":"The base case is a durable routing product with limited owned-liquidity recovery. Watch routed volume and integrations, but pair them with route quality, any disclosed fee capture, KyberDAO rewards, treasury disclosures and whether new Kyber-controlled pools attract capital safely. A stronger case would show reliable routing plus transparent revenue and rebuilt trust. Another router or pool incident, falling integrations, or undisclosed treasury stress would move the outlook lower.","as_of":"2026-08-03","claim_ids":["claim:kyberswap:section:outlook_and_watch:1","claim:kyberswap:section:outlook_and_watch:2","claim:kyberswap:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:kyberswap:routed-volume-24h:2026-08-03","dimension":"spot_volume","label":"Aggregator routed volume, 24h","value":115893602,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 24 hours"},"as_of":"2026-08-03","method":"DefiLlama total24h from the KyberSwap aggregator adapter.","scope":{"product":"aggregator routes","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:kyberswap:metric:routed-volume-24h"],"quality_flags":["routed_volume_overlap","not_owned_liquidity","not_unique_users"]},{"id":"metric:kyberswap:routed-volume-30d:2026-08-03","dimension":"spot_volume","label":"Aggregator routed volume, 30d","value":5260170526,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama total30d from the KyberSwap aggregator adapter.","scope":{"product":"aggregator routes","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:kyberswap:metric:routed-volume-30d"],"quality_flags":["routed_volume_overlap","not_owned_liquidity","not_unique_users"]},{"id":"metric:kyberswap:tvl-latest:2026-08-03","dimension":"tvl","label":"Owned protocol TVL","value":1092494,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported latest point"},"as_of":"2026-08-03","method":"Latest totalLiquidityUSD in the KyberSwap protocol response excluding the separately labeled staking balance.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:kyberswap:metric:tvl-latest"],"quality_flags":["tvl_not_market_depth","aggregator_liquidity_excluded"]},{"id":"metric:kyberswap:exploit-affected-assets:2023-11-22","dimension":"exploit_loss","label":"Elastic affected assets","value":56197284.26,"unit":"usd","currency":"USD","window":{"start":null,"end":"2023-11-22","definition":"incident-time estimate"},"as_of":"2023-11-22","method":"Operator total value of affected assets at incident-time estimates.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:kyberswap:metric:exploit-affected-assets"],"quality_flags":["incident_time_valuation","includes_removed_and_locked_assets"]},{"id":"metric:kyberswap:exploit-bot-recovery:2024-02-07","dimension":"exploit_recovery","label":"Assets recovered from front-running bots","value":5700000,"unit":"usd","currency":"USD","window":{"start":null,"end":"2024-02-07","definition":"recovery reported in post-mortem update"},"as_of":"2024-02-07","method":"Operator approximate recovery from front-running bots.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:kyberswap:metric:exploit-bot-recovery"],"quality_flags":["approximate","not_primary_attacker_recovery","grants_excluded"]}],"events":[{"id":"event:kyberswap:elastic-exploit","type":"exploit","date":"2023-11-22","description":"A precision and tick-accounting flaw in KyberSwap Elastic led to roughly $56.20 million of affected assets.","claim_ids":["claim:kyberswap:event:elastic-exploit"]},{"id":"event:kyberswap:grant-program","type":"user_compensation","date":"2023-12-20","description":"KyberSwap opened a Treasury Grant Program for eligible affected users.","claim_ids":["claim:kyberswap:event:grant-program"]}],"sources":[{"id":"source:kyberswap:overview","title":"Introduction to KyberSwap","url":"https://docs.kyberswap.com/","publisher":