and window.","value":56197284.26,"as_of":"2023-11-22","confidence":"high","kind":"fact","source_ids":["source:kyberswap:postmortem"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kyberswap:metric:exploit-bot-recovery","field_path":"metrics[metric:kyberswap:exploit-bot-recovery:2024-02-07].value","assertion":"Assets recovered from front-running bots was 5700000 USD for the stated scope and window.","value":5700000,"as_of":"2024-02-07","confidence":"high","kind":"fact","source_ids":["source:kyberswap:postmortem"],"evidence_locator":"Provider response replayed between 2026-08-03T18:53:00Z and 2026-08-03T18:58:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kyberswap:event:elastic-exploit","field_path":"events[event:kyberswap:elastic-exploit]","assertion":"A precision and tick-accounting flaw in KyberSwap Elastic led to roughly $56.20 million of affected assets.","value":"2023-11-22","as_of":"2023-11-22","confidence":"high","kind":"fact","source_ids":["source:kyberswap:postmortem","source:kyberswap:blocksec"],"evidence_locator":"Operator incident accounting and independent technical analysis.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kyberswap:event:grant-program","field_path":"events[event:kyberswap:grant-program]","assertion":"KyberSwap opened a Treasury Grant Program for eligible affected users.","value":"2023-12-20","as_of":"2023-12-20","confidence":"high","kind":"fact","source_ids":["source:kyberswap:grant"],"evidence_locator":"Dated program announcement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T18:58:00Z","next_review_at":"2026-08-10T18:58:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["Primary-attacker final recovery","Non-applicant user outcome","Unique retained traders","Audited post-grant profitability"]},"extensions":{"legacy_origin":"dead_exchanges","observation_window":{"started_at":"2026-08-03T18:53:00Z","completed_at":"2026-08-03T18:58:00Z"},"explicit_unknowns":["The final amount recovered directly from the primary attacker is not established in the reviewed update.","The number and value of affected users who did not submit an eligible grant application are not public.","Current unique and retained aggregator traders are not published in a deduplicated form.","Audited company expenses, treasury runway and net profitability after grants are not public."],"identity_boundary":"The legacy dead-exchange row was named KyberSwap Elastic. The canonical profile covers today’s KyberSwap aggregator while preserving Elastic as the exploited and retired pool generation; routed volume is not owned-pool volume.","methodology_notes":["Every material field is attached to atomic pending claims; a person must review those claims before the report can be published.","Routed volume is not additive to underlying DEX volume, notional is not revenue, TVL is not market depth, fees are not profit, and token price is not product success.","Documented decisions, observed outcomes, analyst inferences and unresolved unknowns are kept separate.","KyberSwap aggregator volume overlaps the DEXs that execute the routes and must not be added to their pool volume.","Treasury grants covering approved applicants are user compensation from KyberSwap resources, not evidence that stolen assets were fully recovered from the attacker."]}}', '{"kind":"dex","slug":"kyberswap","lifecycle":"dead","operating_model":"Multi-chain swap aggregator with legacy KyberSwap Elastic pools.","product_cohort":"multi_chain_aggregator_post_exploit","custody_model":"non_custodial","primary_chain":"Ethereum","chains":["Ethereum","Arbitrum","Base","BNB Chain","Polygon","Avalanche","Optimism","Linea","Scroll","zkSync Era"],"token_status":"launched","token_symbol":"KNC","token_launch_date":null,"token_launch_timing":"post_product","token_strategy":"governance_staking_and_pool_fee_rewards","token_source_url":"https://docs.kyberswap.com/governance/kyberdao/faq","metric_type":"aggregator_routed_volume_24h","metric_unit":"usd","metric_window":"rolling_24h","metric_as_of":"2026-08-03","metric_observed_at":"2026-08-03T18:53:00Z","comparability_key":"dex|multi_chain_aggregator|aggregator_routed_volume_24h|usd|rolling_24h","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"The legacy dead-exchange row was named KyberSwap Elastic. The canonical profile covers today’s KyberSwap aggregator while preserving Elastic as the exploited and retired pool generation; routed volume is not owned-pool volume.","metric_replayed_at":"2026-08-03T18:53:00Z","source_count":10},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _dex_wave_f_profiles_0083 (
  target_table, slug, canonical_profile, feature
) VALUES ('dead_exchanges', 'serum', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"dex:serum","type":"dex","slug":"serum","name":"Serum","aliases":["Project Serum","Serum DEX"]},"classification":{"subtype":"retired Solana central-limit order-book protocol","tags":["spot_order_book","solana","ftx_dependency","closed","forked"],"chains":["Solana"],"jurisdictions":[]},"status":{"operating_state":"closed","as_of":"2026-08-03","claim_ids":["claim:serum:status"]},"outcome":{"label":"failed_closed","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:serum:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Serum was an onchain central-limit order book on Solana. Instead of asking every app to build its own book, it offered shared markets that wallets, AMMs and trading interfaces could plug into. The contracts were non-custodial, but the original upgrade authority was controlled through FTX-linked infrastructure. Serum is no longer an operating venue. OpenBook copied the code and replaced it in the Solana ecosystem, so OpenBook activity must not be counted as Serum activity.","as_of":"2026-08-03","claim_ids":["claim:serum:section:what_it_is:1","claim:serum:section:what_it_is:2","claim:serum:section:what_it_is:3"]},"what_happened":{"body":"Serum launched in August 2020 with FTX and Alameda backing and became shared market infrastructure for early Solana DeFi. SRM offered fee discounts and was marketed as a token that would benefit from exchange fees. When FTX collapsed and its wallets were attacked in November 2022, Solana developers could not trust the FTX-held Serum upgrade authority. They forked the program into OpenBook, and major integrations moved within days. Serum then described the original program as defunct. Current DefiLlama short-window volume fields remain null.","as_of":"2026-08-03","claim_ids":["claim:serum:section:what_happened:1","claim:serum:section:what_happened:2","claim:serum:section:what_happened:3","claim:serum:section:what_happened:4"]},"why_this_outcome":{"body":"Serum’s product idea worked well enough to become infrastructure, but governance and token control were not independent of FTX and Alameda. That central dependency was hidden beneath non-custodial trading contracts: users controlled assets, yet the ecosystem still depended on an upgrade key and sponsor that could no longer be trusted. The court record later described FTX and Alameda as SRM’s creators and holders of more than 95% of supply. Because the code was open, Solana could preserve the useful order book by forking it. That made migration rational and left the Serum brand and SRM economics behind.","as_of":"2026-08-03","claim_ids":["claim:serum:section:why_this_outcome:1","claim:serum:section:why_this_outcome:2","claim:serum:section:why_this_outcome:3","claim:serum:section:why_this_outcome:4"]},"strategic_choices":{"body":"Serum chose a shared order book that other Solana applications could compose with, a strong distribution decision. It also tied upgrades, sponsorship and token economics closely to FTX and Alameda. SRM used an extremely large locked allocation and promised fee discounts plus fee-funded benefits, creating a headline fully diluted value supported by a small freely traded supply. The team did not establish a resilient independent upgrade process before its sponsor failed. Open sourcing made recovery possible, but the recovery happened through a new venue and removed Serum’s moat.","as_of":"2026-08-03","claim_ids":["claim:serum:section:strategic_choices:1","claim:serum:section:strategic_choices:2","claim:serum:section:strategic_choices:3","claim:serum:section:strategic_choices:4"]},"operating_model":{"body":"Serum markets matched limit orders on Solana and settled from user-controlled accounts. Third-party interfaces and protocols could create markets, place orders and share the same book. Fees were charged by the order-book program, while integrators could add their own economics. This model depended on crank and integration infrastructure as well as the program itself. After November 2022, applications moved to OpenBook or other maintained programs, so the original Serum operating model no longer has a supported market network.","as_of":"2026-08-03","claim_ids":["claim:serum:section:operating_model:1","claim:serum:section:operating_model:2","claim:serum:section:operating_model:3"]},"token_and_value_capture":{"body":"SRM launched in August 2020 as Serum’s utility and governance token. Holding it reduced trading fees, while archived documentation said exchange fees would generally benefit SRM through buy-and-burn, rewards or grants. Ninety percent of supply began locked, and the later court record says FTX and Alameda controlled more than 95% of total supply. Once integrations migrated to OpenBook, the original fee funnel stopped being a credible value-capture path. SRM does not gain a right to OpenBook activity simply because OpenBook forked Serum code.","as_of":"2026-08-03","claim_ids":["claim:serum:section:token_and_value_capture:1","claim:serum:section:token_and_value_capture:2","claim:serum:section:token_and_value_capture:3","claim:serum:section:token_and_value_capture:4"]},"counterfactual":{"body":"An independent multisig or governance-controlled upgrade authority established before the FTX collapse could have let Serum users rotate keys without abandoning the venue. A less concentrated token distribution could have reduced sponsor and liquidity risk. The same emergency fork might then have been an upgrade rather than a brand migration. Still, FTX’s collapse could have removed market makers and confidence even with better controls, so public evidence cannot prove Serum would have survived.","as_of":"2026-08-03","claim_ids":["claim:serum:section:counterfactual:1","claim:serum:section:counterfactual:2","claim:serum:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The original venue is closed, so current risks are residual rather than growth risks: legacy accounts, inaccessible rent or orders, dormant software, SRM estate sales and confusion between Serum and OpenBook. The public adapter still reports a latest TVL-like balance, but absent current volume and a maintained operator it cannot be treated as live exchange liquidity. Residual user balances, final upgrade-key custody, the full SRM estate disposition and any remaining supported frontends are not established.","as_of":"2026-08-03","claim_ids":["claim:serum:section:risks_and_unknowns:1","claim:serum:section:risks_and_unknowns:2","claim:serum:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Serum launched in August 2020, grew into a shared Solana order book and recorded about $3.49 billion of cumulative volume in the surviving adapter. Its TVL series peaked near $1.88 billion in November 2021. The FTX collapse in November 2022 exposed unsafe upgrade control, and Solana developers rapidly moved to OpenBook. Serum called the original program defunct. The technology influenced successors, but the venue, sponsor network and token value-capture loop ended. This is a failed and closed project with a successful open-source afterlife.","as_of":"2026-08-03","claim_ids":["claim:serum:section:lifecycle:1","claim:serum:section:lifecycle:2","claim:serum:section:lifecycle:3"]},"outlook_and_watch":{"body":"There is no operating recovery thesis for original Serum. The useful watch items are closure hygiene: migration tools for legacy accounts, transparent handling of residual balances, FTX-estate SRM disposition and whether any interface still misrepresents old markets as live. OpenBook or newer Solana order-book growth belongs in their own profiles. A genuine Serum revival would require a maintained program, independent authority, active markets and new evidence of users and fees; none appears in the reviewed record.","as_of":"2026-08-03","claim_ids":["claim:serum:section:outlook_and_watch:1","claim:serum:section:outlook_and_watch:2","claim:serum:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:serum:cumulative-spot-volume:2022-11-29","dimension":"spot_volume","label":"Historical cumulative spot volume","value":3488914577,"unit":"usd","currency":"USD","window":{"start":null,"end":"2022-11-29","definition":"historical cumulative through venue wind-down"},"as_of":"2022-11-29","method":"DefiLlama totalAllTime from the legacy Serum dailyVolume adapter.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:serum:metric:cumulative-spot-volume"],"quality_flags":["historical_not_current","adapter_legacy_scope"]},{"id":"metric:serum:tvl-peak:2021-11-09","dimension":"tvl","label":"Historical peak TVL","value":1881949146,"unit":"usd","currency":"USD","window":{"start":null,"end":"2021-11-09","definition":"historical maximum in provider series"},"as_of":"2021-11-09","method":"Maximum totalLiquidityUSD in the Serum protocol response, dated 2021-11-09.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:serum:metric:tvl-peak"],"quality_flags":["historical_not_current"]}],"events":[{"id":"event:serum:emergency-fork","type":"emergency_migration","date":"2022-11-12","description":"Solana developers began an emergency fork after FTX’s compromise made the Serum upgrade authority unsafe to trust.","claim_ids":["claim:serum:event:emergency-fork"]},{"id":"event:serum:declared-defunct","type":"closure","date":"2022-11-29","description":"Serum described the original mainnet program as defunct and directed the ecosystem toward OpenBook.","claim_ids":["claim:serum:event:declared-defunct"]}],"sources":[{"id":"source:serum:overview","title":"Serum overview","url":"https://docs.projectserum.com/introduction/overview","publisher":"Project Serum","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Archived operator description of the shared Solana order book and product surfaces.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:serum:philosophy","title":"Serum philosophy and architecture","url":"https://docs.projectserum.com/appendix/philosophy","publisher":"Project Serum","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Archived description of permissionless, non-custodial, onchain order-book design.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:serum:token","title":"SRM token","url":"https://docs.projectserum.com/introduction/srm-token","publisher":"Project Serum","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Archived SRM utility, unlock and fee buy-and-burn claims.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:serum:github","title":"Project Serum repositories","url":"https://github.com/orgs/project-serum/repositories","publisher":"GitHub / Project Serum","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Current repository list and last-update dates for the original code organization.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:serum:solana-update","title":"Solana community update: December 2022","url":"https://solana.com/en/news/monthly-community-update-december-2022","publisher":"Solana Foundation","published_at":"2022-12-20","accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Community migration timeline, emergency fork and OpenBook adoption.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:serum:defunct","title":"FTX-backed DEX Serum calls itself defunct","url":"https://www.theblock.co/post/190566/ftx-backed-dex-serum-calls-itself-defunct-promotes-community-fork","publisher":"The Block","published_at":"2022-11-29","accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Independent report of the project statement, FTX-held upgrade authority and OpenBook replacement.","direct_http_status":403,"access_method":"indexed_browser_snapshot"},{"id":"source:serum:fork","title":"Serum emergency fork after FTX hack","url":"https://www.coindesk.com/markets/2022/11/15/serums-srm-tokens-double-in-price-after-emergency-fork-in-wake-of-ftx-hack","publisher":"CoinDesk","published_at":"2022-11-15","accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Independent report of the security concern and emergency fork.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:serum:court","title":"FTX digital-asset estimation appeal opinion","url":"https://www.ded.uscourts.gov/sites/ded/files/opinions/24-804.pdf","publisher":"U.S. District Court for the District of Delaware","published_at":null,"accessed_at":"2026-08-03T18:58:00Z","archive_url":null,"tier":"A","role":"independent","access_state":"reachable","checked_at":"2026-08-03T18:58:00Z","content_hash":null,"evidence_locator":"Court record describing FTX and Alameda creation and ownership of more than 95% of SRM supply.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:serum:volume","title":"Serum DEX volume API","url":"https:/